#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor
{
    [InitializeOnLoad]
    public static class PrisonKeysCheck
    {
        static readonly System.Collections.Generic.HashSet<string> eatingShots=new(); static bool running;static int stage;static float wait;static double deadline;
        const string Log="Logs/Prison-keys-check.txt";
        static PrisonKeysCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("KeysCheck",false)){SessionState.SetBool("KeysCheck",false);running=true;stage=0;deadline=EditorApplication.timeSinceStartup+600;}};}
        public static void Run(){eatingShots.Clear();if(!PrisonChapterCheck.Active)EditorSceneManager.OpenScene("Assets/Scenes/PrisonChapter.unity");File.WriteAllText(Log,"Keys / original pizza / cart / office checks\n");SessionState.SetBool("KeysCheck",true);EditorApplication.EnterPlaymode();}
        static void Check(bool value,string text){File.AppendAllText(Log,(value?"PASS ":"FAIL ")+text+"\n");if(!value)throw new Exception(text);}
        static void Set(object o,string p,object v)=>o.GetType().GetProperty(p).SetValue(o,v);
        static void Place(PrisonKeysMission m,Vector3 p){var player=m.previous.prison.player;var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.position=p+Vector3.up*1.1f;cc.enabled=true;Physics.SyncTransforms();}
        public static void ContinueChapter(){File.WriteAllText(Log,"Continuous chapter test; previous mission state retained\n");running=true;stage=1;wait=Time.time+.5f;deadline=EditorApplication.timeSinceStartup+600;}
        static void Tick(){if(!running||!EditorApplication.isPlaying)return;try{
            var m=Object.FindFirstObjectByType<PrisonKeysMission>();if(!m)return;if(EditorApplication.timeSinceStartup>deadline)throw new Exception("timeout "+stage);
            if(stage==0){stage=1;wait=Time.time+2;return;}foreach(var g in m.diners.Concat(new[]{m.warden})){var e=g.GetComponent<PrisonPizzaEating>();if(e&&e.Playing){int phase=e.Elapsed<1?0:e.Elapsed<2?1:e.Elapsed<4?2:e.Elapsed<5?3:4;string name=g.name+phase;if(eatingShots.Add(name)){var cam=m.camera;var pos=cam.transform.position;var rot=cam.transform.rotation;cam.transform.position=g.transform.position+g.transform.forward*2.3f+g.transform.right*.6f+Vector3.up*1.35f;cam.transform.LookAt(g.transform.position+Vector3.up*1.1f);PrisonChickenCheck.Capture(cam,"Logs/Eating-"+name+".png");cam.transform.SetPositionAndRotation(pos,rot);}}} if(Time.time<wait)return;
            var player=m.previous.prison.player;var inventory=player.GetComponent<ToppingInventory>();
            if(stage==1){if(PrisonChapterCheck.Active){eatingShots.Clear();m.dialogue=Object.Instantiate(m.dialogue);m.dialogue.lineSeconds=.05f;stage=2;return;}var intro=m.previous.prison.introduction;intro.StopAllCoroutines();typeof(PrisonIntroduction).GetMethod("SetCinematic",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(intro,new object[]{false});Set(intro,"State",PrisonIntroduction.Stage.Complete);Set(intro,"Fade",0f);intro.mugshotActor.gameObject.SetActive(false);Set(m.previous.chicken,"State",PrisonChickenMission.Stage.Complete);Set(m.previous,"State",PrisonMedicineMission.Stage.Complete);m.dialogue=Object.Instantiate(m.dialogue);m.dialogue.lineSeconds=.05f;stage=2;wait=Time.time+.5f;return;}
            if(stage==2){Check(m.State==PrisonKeysMission.Stage.Steal,"medicine completion unlocks keys"); Check(NavMesh.SamplePosition(m.keyGuard.transform.position,out var alley, .8f,NavMesh.AllAreas),"alley patrol has navigation ground"); var alleyPath=new NavMeshPath(); Check(NavMesh.CalculatePath(m.checkpoint.position-Vector3.up*1.1f,alley.position,NavMesh.AllAreas,alleyPath)&&alleyPath.status==NavMeshPathStatus.PathComplete,"alley checkpoint connects to patrol");m.keyGuard.enabled=false;m.keyGuard.GetComponent<NavMeshAgent>().isStopped=true;m.keyGuard.transform.rotation=Quaternion.Euler(0,90,0);Place(m,m.keyGuard.transform.position+m.keyGuard.transform.forward*1.2f);Check(!m.CanSteal(),"cannot steal from front");Place(m,m.keyGuard.transform.position-m.keyGuard.transform.forward*1.2f);Check(m.CanSteal(),"can steal from behind");InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.F));stage=3;wait=Time.time+1;return;}
            if(stage==3){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());Check(m.State==PrisonKeysMission.Stage.Unlock&&!m.keyRing.activeSelf,"holding F steals key ring");Place(m,m.keyGuard.transform.position+m.keyGuard.transform.forward*2);stage=4;wait=Time.time+2.1f;return;}
            if(stage==4){if(m.Failing)return;Check(m.State==PrisonKeysMission.Stage.Steal&&player.CanAct,"being seen retries only keys mission");Check(m.previous.State==PrisonMedicineMission.Stage.Complete,"previous mission retained");m.keyGuard.enabled=false;m.keyGuard.GetComponent<NavMeshAgent>().isStopped=true;m.keyGuard.transform.rotation=Quaternion.Euler(0,90,0);Place(m,m.keyGuard.transform.position-m.keyGuard.transform.forward*1.2f);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.F));stage=5;wait=Time.time+1;return;}
            if(stage==5){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());m.keyGuard.GetComponent<NavMeshAgent>().Warp(new Vector3(-23,0,14));m.keyGuard.transform.rotation=Quaternion.Euler(0,90,0);Place(m,m.keyLock.transform.position+Vector3.back*.6f-Vector3.up*1.15f);Check(m.Interact()&&m.SelectingKey,"lock interaction blocks attacks");Check(m.keyLock.Turn(2)==-1,"wrong key does not open door");m.keyLock.Select(1);m.keyLock.Select(1);InputSystem.QueueStateEvent(Mouse.current,new MouseState().WithButton(MouseButton.Left));stage=6;wait=Time.time+2.2f;return;}
            if(stage==6){InputSystem.QueueStateEvent(Mouse.current,new MouseState());Check(m.State==PrisonKeysMission.Stage.Gather&&m.keyLock.Opened&&player.CanAct,"correct key opens door and restores movement");PrisonChickenCheck.Capture(player.View,"Logs/Keys-pantry.png");foreach(var s in m.supplies){Place(m,s.transform.position-Vector3.up*s.transform.position.y+Vector3.back*.8f);Check(m.Interact(),"collect "+s.name);}Check(m.State==PrisonKeysMission.Stage.Cook,"supplies unlock cooking");
                inventory.AddItem(m.ingredients[0]);m.maker.Interact(inventory);for(int i=1;i<4;i++){inventory.AddItem(m.ingredients[i]);m.maker.Interact(inventory);}m.maker.Interact(inventory);Check(inventory.HeldPizza&&!inventory.HeldPizza.GetComponent<Pizza>().IsBaked,"original pizza maker assembles recipe");m.oven.Interact(inventory);stage=7;wait=Time.time+5.5f;return;}
            if(stage==7){m.oven.Interact(inventory);Check(inventory.HeldPizza&&m.ValidPizza(inventory.HeldPizza.GetComponent<Pizza>()),"original oven bakes correct pizza");stage=8;wait=Time.time+.2f;return;}
            if(stage==8){Check(m.State==PrisonKeysMission.Stage.Load,"baked recipe unlocks cart loading");Place(m,m.loadPoint.position+Vector3.back);Check(m.Interact(),"cart accepts pizza");stage=9;wait=Time.time+1;return;}
            if(stage==9){Check(m.State==PrisonKeysMission.Stage.Serve&&m.pizzaOnCart.activeSelf&&!inventory.HasPizza(),"pizza loaded without duplicate inventory");foreach(var target in m.diners.Select(g=>g.transform).Concat(new[]{m.warden.transform})){NavMesh.SamplePosition(m.loadPoint.position,out var a,3,NavMesh.AllAreas);NavMesh.SamplePosition(target.position,out var b,2,NavMesh.AllAreas);var path=new NavMeshPath();Check(NavMesh.CalculatePath(a.position,b.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete,"route to "+target.name);}if(SessionState.GetBool("PrisonCartCheck",false)){SessionState.SetBool("PrisonCartCheck",false);player.gameObject.AddComponent<PrisonCartRouteCheck>();stage=14;}else stage=10;}
            if(stage==14){var drive=player.GetComponent<PrisonCartRouteCheck>();if(!drive.Done)return;Check(drive.Failure==null,"physical cart delivery: "+drive.Failure);stage=11;} if(stage==10){if(m.State==PrisonKeysMission.Stage.Office){stage=11;return;}var guard=m.diners[m.Served];guard.enabled=false;guard.GetComponent<NavMeshAgent>().isStopped=true;var cart=m.previous.prison.cart;cart.transform.position=guard.transform.position+Vector3.back*2;cart.controller.cartRigidbody.position=cart.transform.position;Place(m,guard.transform.position+Vector3.forward*1.6f);Check(m.Interact(),"serve "+guard.name);wait=Time.time+guard.GetComponent<PrisonPizzaEating>().Duration+4;return;}
            if(stage==11){var space=m.GetComponent<PrisonMissionSpace>();Check(space.population.slots.All(s=>!s.actor||!s.actor.gameObject.activeInHierarchy||!space.Restricted(s.actor.transform.position)),"ordinary NPCs excluded from serving area");Check(m.officeDoor.gameObject.activeSelf&&m.officeDoor.GetComponent<PrisonOfficeEntrance>().IsOpen&&m.diners.All(g=>g.GetComponent<NPCControl>().IsKnockedDown),"guards sleep and hinged door stays visible and open");var friend=m.previous.prison.introduction.mingi;friend.agent.Warp(new Vector3(-13,3.75f,-31));Place(m,new Vector3(-13,3.75f,-31.8f));stage=13;wait=Time.time+9;return;} if(stage==13){var friend=m.previous.prison.introduction.mingi;File.AppendAllText(Log,$"ENTRY pos={friend.transform.position} goal={m.officeDoor.GetComponent<PrisonOfficeEntrance>().insideWait.position} path={friend.agent.pathStatus} remaining={friend.agent.remainingDistance} scripted={friend.ScriptedTravel}\\n".Replace("\\n","\n"));Check(m.officeDoor.GetComponent<PrisonOfficeEntrance>().CompanionArrived,"Mingi walks through open doorway to inside waiting point");var cam=m.camera;cam.transform.position=new Vector3(-11,5.4f,-33);cam.transform.LookAt(new Vector3(-18,4.8f,-30));PrisonChickenCheck.Capture(cam,"Logs/Prison-office-entrance.png");m.warden.enabled=false;m.warden.GetComponent<NavMeshAgent>().isStopped=true;Place(m,m.warden.transform.position+Vector3.right*1.6f);Check(m.Interact(),"warden conversation starts");stage=12;wait=Time.time+m.warden.GetComponent<PrisonPizzaEating>().Duration+1;return;}
            if(stage==12){Check(m.diners.Concat(new[]{m.warden}).All(g=>g.GetComponent<PrisonPizzaEating>().Finished&&!g.GetComponent<PrisonPizzaEating>().slice.gameObject.activeSelf),"all four actors finish eating and hide slices");Check(m.State==PrisonKeysMission.Stage.Complete&&player.CanAct&&m.warden.GetComponent<NPCControl>().IsKnockedDown,"warden sleeps and gameplay resumes");File.AppendAllText(Log,"NOTE input events tested for theft and lock; travel seeded, pizza uses original public interactions; route checks do not simulate full cart driving\n");running=false;if(PrisonChapterCheck.Active)PrisonChapterCheck.Finish(!System.IO.File.ReadAllText(Log).Contains("Exception"));else EditorApplication.ExitPlaymode();}
        }catch(Exception e){File.AppendAllText(Log,e.ToString());InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());InputSystem.QueueStateEvent(Mouse.current,new MouseState());running=false;if(PrisonChapterCheck.Active)PrisonChapterCheck.Finish(!System.IO.File.ReadAllText(Log).Contains("Exception"));else EditorApplication.ExitPlaymode();}}
    }
}
#endif


